H.background();
const w = H.W, h = H.H;
// Atomic spectra (hydrogen): an electron drops from n_hi to n_lo, emitting a
// photon.  1/lambda = R*(1/n_lo^2 - 1/n_hi^2),  R = 1.097e7 /m.
const nLo = Math.round(P.nlow);     // lower level (2 = Balmer, visible)
let nHi = Math.round(P.nhigh);      // upper level
if (nHi <= nLo) nHi = nLo + 1;      // guard: emission needs n_hi > n_lo
const R = 1.097e7;                  // Rydberg constant, /m
const invLam = R * (1 / (nLo * nLo) - 1 / (nHi * nHi));   // 1/m
const lambda_m = invLam > 0 ? 1 / invLam : Infinity;
const lambda_nm = lambda_m * 1e9;
const Ephoton_eV = 1239.84 / lambda_nm;   // hc/lambda with hc = 1239.84 eV*nm
// visible color of the emitted line
function waveColor(nm) {
  if (nm < 380) return H.colors.violet;          // UV (draw as violet)
  if (nm < 450) return "#8a7bff";
  if (nm < 490) return "#5aa9ff";
  if (nm < 560) return H.colors.good;
  if (nm < 590) return H.colors.yellow;
  if (nm < 635) return H.colors.accent2;
  if (nm < 750) return H.colors.warn;
  return "#b85a5a";                              // IR (draw as deep red)
}
const col = waveColor(lambda_nm);
// --- left: energy-level drop ---
const lx = w * 0.10, lw = w * 0.30;
const topY = h * 0.16, botY = h * 0.74;
function Ey(E) { return H.map(E, -13.6, 0, botY, topY); }
H.text("electron drops n=" + nHi + " → n=" + nLo, lx, topY - 18, { color: H.colors.sub, size: 12 });
// draw enough levels to include the upper level (n_hi can reach 7)
const kMax = Math.max(6, nHi);
for (let k = 1; k <= kMax; k++) {
  const Ek = -13.6 / (k * k);
  const yk = Ey(Ek);
  const hot = (k === nLo || k === nHi);
  H.line(lx, yk, lx + lw, yk, { color: hot ? H.colors.ink : H.colors.grid, width: hot ? 2.5 : 1.2 });
  H.text("n=" + k, lx + lw + 6, yk + 4, { color: hot ? H.colors.ink : H.colors.sub, size: 11 });
}
// the falling electron, animated; loops: starts at n_hi, falls to n_lo, resets
const fall = (t % 2.4) / 2.4;
const yHi = Ey(-13.6 / (nHi * nHi));
const yLo = Ey(-13.6 / (nLo * nLo));
const eY = H.lerp(yHi, yLo, H.ease(fall));
const eX = lx + lw * 0.5;
H.arrow(eX, yHi, eX, yLo, { color: col, width: 2, head: 8 });
H.circle(eX, eY, 7, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
// emitted photon shoots right when the electron lands
if (fall > 0.85) {
  const pp = (fall - 0.85) / 0.15;
  const phx = H.lerp(eX, w - 60, pp);
  const wp = [];
  for (let i = 0; i <= 30; i++) {
    const xx = phx - 40 + i * 1.4;
    if (xx < lx + lw) continue;
    wp.push([xx, yLo + 8 * Math.sin(i * 0.9 + t * 6)]);
  }
  if (wp.length >= 2) H.path(wp, { color: col, width: 2.5 });
}
// --- right: spectral line on a wavelength ruler ---
const sx = w * 0.50, sw = w * 0.44;
const ruleY = h * 0.86;
H.line(sx, ruleY, sx + sw, ruleY, { color: H.colors.axis, width: 2 });
// ruler from 380 to 750 nm (visible band)
const nmMin = 380, nmMax = 750;
for (let nm = 400; nm <= 700; nm += 100) {
  const tx = H.map(nm, nmMin, nmMax, sx, sx + sw);
  H.line(tx, ruleY - 4, tx, ruleY + 4, { color: H.colors.sub, width: 1 });
  H.text(nm + "", tx, ruleY + 18, { color: H.colors.sub, size: 10, align: "center" });
}
H.text("wavelength (nm)", sx + sw * 0.5, ruleY + 34, { color: H.colors.sub, size: 11, align: "center" });
// the emission line, blinking
if (isFinite(lambda_nm) && lambda_nm >= nmMin && lambda_nm <= nmMax) {
  const linex = H.map(lambda_nm, nmMin, nmMax, sx, sx + sw);
  const glow = 0.6 + 0.4 * Math.abs(Math.sin(t * 3));
  H.line(linex, ruleY - 70, linex, ruleY, { color: col, width: 3 });
  H.circle(linex, ruleY - 70, 4 + 2 * glow, { fill: col });
  H.text(lambda_nm.toFixed(0) + " nm", linex, ruleY - 80, { color: col, size: 12, align: "center", weight: 700 });
} else {
  H.text("line at " + (isFinite(lambda_nm) ? lambda_nm.toFixed(0) + " nm (outside visible band)" : "∞"), sx + sw * 0.5, ruleY - 40, { color: H.colors.sub, size: 12, align: "center" });
}
// title + readouts
H.text("Atomic spectra:  1/λ = R(1/n_lo² − 1/n_hi²)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("n_lo = " + nLo + ",  n_hi = " + nHi + "    R = 1.097×10⁷ /m", 24, 56, { color: H.colors.sub, size: 13 });
H.text("λ = " + (isFinite(lambda_nm) ? lambda_nm.toFixed(1) + " nm" : "∞") + "    E = " + Ephoton_eV.toFixed(2) + " eV", 24, 76, { color: col, size: 14, weight: 700 });
H.legend([{ label: "emitted photon", color: col }], w - 175, 28);
